sys_script_client.script:
function onLoad() {
    //MSSCUSTODY-6826
    // Only run for checker task
    if (g_form.getValue('trade_task_type') == 'Checker') {

        var payloadToFormFieldMapping = {
            "security_id_previous": "security_id_sec_id",
            "security_id_current": "security_id_sec_id",
            "trade_date_previous": "amend_trade_date",
            "trade_date_current": "amend_trade_date",
            "settlement_date_previous": "settlement_date",
            "settlement_date_current": "settlement_date",
            "deal_price_currency_previous": "amend_deal_price_currency",
            "deal_price_currency_current": "amend_deal_price_currency",
            "deal_price_previous": "amend_deal_price",
            "deal_price_current": "amend_deal_price",
            "settlement_amount_currency_previous": "amend_settlement_currency",
            "settlement_amount_currency_current": "amend_settlement_currency",
            "settlement_amount_previous": "amend_settlement_amount",
            "settlement_amount_current": "amend_settlement_amount",
            "counterparty_reference_previous": "counterparty_reference",
            "counterparty_reference_current": "counterparty_reference",
            "customer_reference_previous": "customer_reference",
            "customer_reference_current": "customer_reference",
            "location_code_previous": "amend_location_code",
            "location_code_current": "amend_location_code",
            "hold_matched_si_indicator_previous": "amend_hmi_indicator",
            "hold_matched_si_indicator_current": "amend_hmi_indicator",
            "script_hold_indicator_previous": "amend_script_hold_indicator",
            "script_hold_indicator_current": "amend_script_hold_indicator",
            "cash_hold_indicator_previous": "amend_cash_hold_indicator",
            "cash_hold_indicator_current": "amend_cash_hold_indicator",
            "gdi_indicator_previous": "amend_gdi_indicator",
            "gdi_indicator_current": "amend_gdi_indicator",
            "cash_payment_method_previous": "amend_cash_payment_method",
            "cash_payment_method_current": "amend_cash_payment_method",
            "switch_indicator_previous": "amend_swift_indicator",
            "switch_indicator_current": "amend_swift_indicator",
            "suspense_account_number_previous": "amend_suspense_account_number",
            "suspense_account_number_current": "amend_suspense_account_number",
            "switch_account_previous": "amend_switch_account",
            "switch_account_current": "amend_switch_account",
            "counterparty_code_previous": "amend_counterparty_code",
            "counterparty_code_current": "amend_counterparty_code",
            "counterparty_settlement_account_number_previous": "amend_counterparty_settlement_account_number",
            "counterparty_settlement_account_number_current": "amend_counterparty_settlement_account_number",
            "convert_to_account_switching_previous": "amend_convert_to_account_switching",
            "convert_to_account_switching_current": "amend_convert_to_account_switching",
            "a_c_of_client_previous": "amend_a_c_of_client",
            "a_c_of_client_current": "amend_a_c_of_client",
            "deliver_custodian_bic_previous": "amend_deliverer_custodian_bic_receiver_custodian_bic", //MSSCUSTODY-7151
            "deliver_custodian_bic_current": "amend_deliverer_custodian_bic_receiver_custodian_bic", //MSSCUSTODY-7151
			"receiver_custodian_bic_previous": "amend_receiver_custodian_bic", //MSSCUSTODY-7151
            "receiver_custodian_bic_current": "amend_receiver_custodian_bic",  //MSSCUSTODY-7151
            "place_of_settlement_95a_qualifier_pset_previous": "amend_place_of_settlement_bic",
            "place_of_settlement_95a_qualifier_pset_current": "amend_place_of_settlement_bic",
            "seller_bic_previous": "amend_seller_bic", //MSSCUSTODY-7151
            "seller_bic_current": "amend_seller_bic",//MSSCUSTODY-7151
			"buyer_bic_previous": "amend_buyer_bic",//MSSCUSTODY-7151
            "buyer_bic_current": "amend_buyer_bic",//MSSCUSTODY-7151
            "amend_charges_type_previous": "amend_charges_type",
            "amend_charges_type_current": "amend_charges_type",
            "amend_charges_ccy_previous": "amend_charges_ccy",
            "amend_charges_ccy_current": "amend_charges_ccy",
            "amend_charges_amt_previous": "amend_charges_amt",
            "amend_charges_amt_current": "amend_charges_amt",
            "amend_nssc_previous": "amend_nssc",
            "amend_nssc_current": "amend_nssc"
        };

        g_form.getReference('trade_id', function(tradeData) {
            var tradeAudit = tradeData.trade_audit;
            if (!tradeAudit) return;

            try {
                var auditObj = JSON.parse(tradeAudit);
                if (Array.isArray(auditObj.checker_approval) && auditObj.checker_approval.length > 0) {
                    var latestAmend = auditObj.checker_approval[auditObj.checker_approval.length - 1];
                    for (var key in latestAmend) {
                        if (key.endsWith('_current')) {
                            var fieldName = key.replace('_current', '');
                            var currentValue = latestAmend[key];
                            var previousValue = latestAmend[fieldName + '_previous'];
                            if (currentValue != previousValue) {
                                var formField = payloadToFormFieldMapping[key];
                                if (formField) {
                                    // Try all possible field name variants
                                    var fieldVariants = [
                                        'sys_readonly.x_hsb11_mss_c_proc_mss_custody_task.bulk_id.' + formField,
                                        'bulk_id.' + formField,
                                        formField
                                    ];

                                    // Highlight the label (works for all)
                                    for (var i = 0; i < fieldVariants.length; i++) {
                                        var label = g_form.getLabel(fieldVariants[i]);
                                        if (label && label.style) {
                                            label.style.color = '#4682B4';
                                            break; // Stop at first found
                                        }
                                    }
                                    for (var i = 0; i < fieldVariants.length; i++) {
                                        var box = g_form.getDisplayBox(fieldVariants[i]);
                                        if (box) {
                                            box.style.backgroundColor = '#C3DFF0';
                                            break;
                                        }
                                        var control = g_form.getControl(fieldVariants[i]);
                                        if (control) {
                                            control.style.backgroundColor = '#C3DFF0';
                                            break;
                                        }
                                    }

                                }
                            }
                        }

                    }
                }


            } catch (e) {
                g_form.addErrorMessage('Error in highlighting the checker approval fields: ' + e.message);
            }
        });
    } else {
        return;
    }
}
